#include <iostream>

// Mô phỏng cơ chế header guard trong cùng một tệp dịch
#ifndef SIMULATED_CIRCLE_H
#define SIMULATED_CIRCLE_H

class Circle {
public:
    Circle();
    Circle(double r);
    double getArea() const;

private:
    double radius;
};

#endif // SIMULATED_CIRCLE_H

// Lần nạp thứ hai của header (sẽ bị tiền xử lý bỏ qua hoàn toàn)
#ifndef SIMULATED_CIRCLE_H
#define SIMULATED_CIRCLE_H
class Circle { double duplicate; };
#endif

// Triển khai phương thức
Circle::Circle() : radius(1.0) {}
Circle::Circle(double r) : radius(r) {}
double Circle::getArea() const {
    return radius * radius * 3.14159;
}

int main() {
    Circle c1;
    Circle c2(6.0);
    c1 = c2;
    std::cout << "c1 area: " << c1.getArea() << "\n";
    std::cout << "anon area: " << Circle(8.0).getArea() << "\n";
    return 0;
}

#include <iostream>

class Circle {
public:
    // Hàm inline định nghĩa trực tiếp trong lớp
    Circle() : radius(1.0) {}
    Circle(double newRadius) {
        setRadius(newRadius);
    }

    // Accessor (hàm inline tự động, đánh dấu const theo chuẩn C++ hiện đại)
    double getRadius() const {
        return radius;
    }

    // Mutator kiểm soát tính toàn vẹn
    void setRadius(double newRadius);

    double getArea() const;

private:
    double radius;
};

// Định nghĩa ngoài lớp với từ khóa inline
inline void Circle::setRadius(double newRadius) {
    radius = (newRadius >= 0.0) ? newRadius : 0.0;
}

inline double Circle::getArea() const {
    return radius * radius * 3.14159;
}

int main() {
    Circle c1;
    Circle c2(5.0);

    std::cout << "c1 radius: " << c1.getRadius() << ", area: " << c1.getArea() << "\n";
    std::cout << "c2 radius: " << c2.getRadius() << ", area: " << c2.getArea() << "\n";

    // Thử nghiệm mutator ngăn chặn giá trị không hợp lệ
    c2.setRadius(-10.0);
    std::cout << "After negative update -> c2 radius: " << c2.getRadius() << ", area: " << c2.getArea() << "\n";

    c2.setRadius(100.0);
    std::cout << "After valid update -> c2 radius: " << c2.getRadius() << ", area: " << c2.getArea() << "\n";

    return 0;
}
